  `MstRtAxe2` INT UNSIGNED NOT NULL DEFAULT 0,
  `MstRtMace1` INT UNSIGNED NOT NULL DEFAULT 0,
  `MstRtBow2` INT UNSIGNED NOT NULL DEFAULT 0,
  `MstRtCrossBow2` INT UNSIGNED NOT NULL DEFAULT 0,
  `MstRtWand2` INT UNSIGNED NOT NULL DEFAULT 0,
  `MstRtStaff2` INT UNSIGNED NOT NULL DEFAULT 0,
  `MstRtClaw` INT UNSIGNED NOT NULL DEFAULT 0,
  `MstRtDSword` INT UNSIGNED NOT NULL DEFAULT 0,
  `MstPlTmp` INT UNSIGNED NOT NULL DEFAULT 0,
  `MstPlSword1` INT UNSIGNED NOT NULL DEFAULT 0,
  `MstPlHammer1` INT UNSIGNED NOT NULL DEFAULT 0,
  `MstPlSword2` INT UNSIGNED NOT NULL DEFAULT 0,
  `MstPlAxe2` INT UNSIGNED NOT NULL DEFAULT 0,
  `MstPlMace1` INT UNSIGNED NOT NULL DEFAULT 0,
  `MstPlBow2` INT UNSIGNED NOT NULL DEFAULT 0,
  `MstPlCrossBow2` INT UNSIGNED NOT NULL DEFAULT 0,
  `MstPlWand2` INT UNSIGNED NOT NULL DEFAULT 0,
  `MstPlStaff2` INT UNSIGNED NOT NULL DEFAULT 0,
  `MstPlClaw` INT UNSIGNED NOT NULL DEFAULT 0,
  `MstPlDSword` INT UNSIGNED NOT NULL DEFAULT 0,
